DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='pitlane_auth') THEN CREATE ROLE pitlane_auth NOLOGIN NOBYPASSRLS;END IF;END $$;
GRANT USAGE ON SCHEMA pitlane TO pitlane_auth;
CREATE TABLE IF NOT EXISTS pitlane.auth_sessions(cookie_hash text PRIMARY KEY,user_id uuid NOT NULL,cipher text NOT NULL,csrf text NOT NULL,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS pitlane.request_windows(key text,window_start timestamptz,count integer NOT NULL DEFAULT 0,PRIMARY KEY(key,window_start));
CREATE OR REPLACE FUNCTION pitlane.create_session(h text,u uuid,c text,s text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ INSERT INTO pitlane.auth_sessions VALUES(h,u,c,s,now()+interval '7 days',false) $$;
CREATE OR REPLACE FUNCTION pitlane.read_session(h text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT to_jsonb(s) FROM pitlane.auth_sessions s WHERE cookie_hash=h AND NOT revoked AND expires_at>now() $$;
CREATE OR REPLACE FUNCTION pitlane.update_session(h text,c text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ UPDATE pitlane.auth_sessions SET cipher=c WHERE cookie_hash=h AND NOT revoked AND expires_at>now() $$;
CREATE OR REPLACE FUNCTION pitlane.revoke_session(h text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ UPDATE pitlane.auth_sessions SET revoked=true WHERE cookie_hash=h $$;
CREATE OR REPLACE FUNCTION pitlane.user_tenants(u uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'role',m.role)),'[]'::jsonb) FROM pitlane.tenant_memberships m JOIN pitlane.tenants t ON t.id=m.tenant_id WHERE m.user_id=u AND m.active AND t.deleted_at IS NULL $$;
CREATE OR REPLACE FUNCTION pitlane.rate_limit(k text,maximum integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE n integer;w timestamptz=date_trunc('minute',now());BEGIN IF maximum<1 OR maximum>600 THEN RAISE EXCEPTION 'INVALID_RATE_LIMIT';END IF;INSERT INTO pitlane.request_windows VALUES(k,w,1) ON CONFLICT(key,window_start) DO UPDATE SET count=request_windows.count+1 RETURNING count INTO n;RETURN n<=maximum;END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pitlane FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pitlane.create_session(text,uuid,text,text),pitlane.read_session(text),pitlane.update_session(text,text),pitlane.revoke_session(text),pitlane.user_tenants(uuid),pitlane.rate_limit(text,integer) TO pitlane_auth;
ALTER TABLE pitlane.entitlement_lots ADD COLUMN IF NOT EXISTS origin text NOT NULL DEFAULT 'internal' CHECK(origin IN('internal','customer'));
